def test_non_dict_patch_rejected(bad: object) -> None:
    with pytest.raises(PatchError, match="must be a JSON object"):
        validate_patch(bad)


@pytest.mark.parametrize(
    "patch",
    [
        {"summary": "x"},
        {"summary": "x", "files": []},
        {"summary": "x", "files": None},
        {"summary": "x", "files": {"path": "a.py"}},
        {"summary": "x", "files": "a.py"},
    ],
)
def test_files_must_be_non_empty_list(patch: dict) -> None:
    with pytest.raises(PatchError, match="non-empty 'files' list"):
        validate_patch(patch)


